    design: dict[str, Any] | None = None,
) -> list[str]:
    """Phase 07: one Harbor-style tests/test.sh per approved candidate."""
    errors: list[str] = []
    candidates_dir = Path(candidates_dir)
    approved = review.get("approved_candidate_ids")
