    if (redis_fsync(job->fd_args.fd) == -1 &&
        errno != EBADF && errno != EINVAL)
    {
        int last_status;
        atomicGet(server.aof_bio_fsync_status,last_status);
        atomicSet(server.aof_bio_fsync_status,C_ERR);
        atomicSet(server.aof_bio_fsync_errno,errno);
        if (last_status == C_OK) {
